const board=document.createElement('div');Object.assign(board.style,{width:'min(94vw,500px)',aspectRatio:'1',display:'grid',gridTemplateColumns:'repeat(4,1fr)',gap:'7px',padding:'8px',background:'#111217',border:'1px solid #34373d'});stage.appendChild(board);let a=Array(16).fill(0),score=0;metric('score','0');metric('high_score',localStorage.getItem('arcade-2048')||'0');metric('largest_tile','0');state('RUNNING — arrows/WASD');function add(){let e=a.map((v,i)=>v?null:i).filter(x=>x!==null);if(e.length)a[e[Math.random()*e.length|0]]=Math.random()<.9?2:4}function draw(){board.innerHTML='';a.forEach(v=>{let d=document.createElement('div');d.textContent=v||'';Object.assign(d.style,{display:'grid',placeItems:'center',font:'700 26px Roboto Mono,monospace',background:v?['#5794f2','#73bf69','#ff9830','#b877d9','#f2495c','#e0b400'][Math.min(5,Math.log2(v)-1)]:'#22252b',color:v?'#111':'#9fa7b3'});board.appendChild(d)});set('score',score);let h=Math.max(+localStorage.getItem('arcade-2048')||0,score);localStorage.setItem('arcade-2048',h);set('high_score',h);set('largest_tile',Math.max(...a))}function move(dir){let changed=false;for(let n=0;n<4;n++){let ids=dir==='left'?[n*4,n*4+1,n*4+2,n*4+3]:dir==='right'?[n*4+3,n*4+2,n*4+1,n*4]:dir==='up'?[n,n+4,n+8,n+12]:[n+12,n+8,n+4,n];let v=ids.map(i=>a[i]).filter(Boolean);for(let i=0;i<v.length-1;i++)if(v[i]===v[i+1]){v[i]*=2;score+=v[i];v.splice(i+1,1)}while(v.length<4)v.push(0);ids.forEach((i,j)=>{if(a[i]!==v[j])changed=true;a[i]=v[j]})}if(changed)add();draw()}root.addEventListener('keydown',e=>{let k=e.key.toLowerCase(),d={arrowleft:'left',a:'left',arrowright:'right',d:'right',arrowup:'up',w:'up',arrowdown:'down',s:'down'}[k];if(d){e.preventDefault();move(d)}});add();add();draw();
